t.script:
//
    function toggleFilterDropdown(btn) {
        var dropdown = btn.parentElement;
        var wasOpen = dropdown.classList.contains('open');

        // Close all other dropdowns first
        document.querySelectorAll('.filter-dropdown').forEach(function(d) {
            d.classList.remove('open');
        });

        // Toggle current dropdown if it wasn't open
        if (!wasOpen) {
            dropdown.classList.add('open');

            // On mobile, position dropdown below the filter bar
            if (window.innerWidth <= 768) {
                var filterBar = document.querySelector('.filter-bar-section');
                var menu = dropdown.querySelector('.filter-dropdown-menu');
                if (filterBar && menu) {
                    var rect = filterBar.getBoundingClientRect();
                    menu.style.top = (rect.bottom + 10) + 'px';
                }
            }
        }
    }

    // Close dropdown when clicking outside or on overlay
    document.addEventListener('click', function(e) {
        // Don't close if clicking inside dropdown menu (let link work)
        if (e.target.closest('.filter-dropdown-menu')) {
            return;
        }

        // Close if clicking outside dropdown entirely
        if (!e.target.closest('.filter-dropdown-btn')) {
            document.querySelectorAll('.filter-dropdown').forEach(function(dropdown) {
                dropdown.classList.remove('open');
            });
        }
    });

    // Close on escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            document.querySelectorAll('.filter-dropdown').forEach(function(dropdown) {
                dropdown.classList.remove('open');
            });
        }
    });

    // Handle touch events for better mobile UX
    document.addEventListener('touchstart', function(e) {
        // If touching outside dropdown, close it
        if (!e.target.closest('.filter-dropdown')) {
            document.querySelectorAll('.filter-dropdown').forEach(function(dropdown) {
                dropdown.classList.remove('open');
            });
        }
    }, {passive: true});

    // Update sort while preserving other params
    function updateSort(sortValue) {
        var url = new URL(window.location.href);
        url.searchParams.set('sort_by', sortValue);
        window.location.href = url.toString();
    }

    // Recalculate dropdown position on resize
    window.addEventListener('resize', function() {
        document.querySelectorAll('.filter-dropdown.open').forEach(function(dropdown) {
            dropdown.classList.remove('open');
        });
    });
//
